// Country and language names as a native speaker writes them (España, Deutschland, 日本, Español,
// Deutsch, 日本語), plus hidden search tags with the name in many languages, so "spain", "espagne",
// "spanien" or "スペイン" all find España.
import { LANGUAGES, getLang } from './i18n.js';
import { callingCode } from './shared.js';

export const fold = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

// Languages used only for the hidden search tags (names are generated by the browser, nothing to translate)
const TAG_LANGS = [
  'af', 'am', 'ar', 'az', 'be', 'bg', 'bn', 'bs', 'ca', 'cs', 'cy', 'da', 'de', 'el', 'en', 'es', 'et', 'eu', 'fa', 'fi',
  'fil', 'fr', 'ga', 'gl', 'gu', 'ha', 'he', 'hi', 'hr', 'hu', 'hy', 'id', 'ig', 'is', 'it', 'ja', 'jv', 'ka', 'kk', 'km',
  'kn', 'ko', 'ky', 'lo', 'lt', 'lv', 'mk', 'ml', 'mn', 'mr', 'ms', 'mt', 'my', 'nb', 'ne', 'nl', 'or', 'pa', 'pl', 'ps',
  'pt', 'qu', 'ro', 'ru', 'si', 'sk', 'sl', 'so', 'sq', 'sr', 'sr-Latn', 'sv', 'sw', 'ta', 'te', 'tg', 'th', 'tk', 'tr', 'uk',
  'ur', 'uz', 'vi', 'xh', 'yo', 'zh', 'zh-Hant', 'zu'
];

const displayNames = new Map();
function dn(locale, type){
  const key = `${locale}|${type}`;
  if (!displayNames.has(key)) {
    try { displayNames.set(key, new Intl.DisplayNames([locale], { type, fallback: 'none' })); }
    catch { displayNames.set(key, null); }
  }
  return displayNames.get(key);
}
const nameIn = (locale, type, code) => { try { return dn(locale, type)?.of(code) || ''; } catch { return ''; } };

// The language people speak in that country, with its script (CN → zh-Hans, RS → sr-Cyrl, IN → hi)
const nativeLocaleCache = new Map();
function nativeLocale(country){
  if (!nativeLocaleCache.has(country)) {
    let locale = 'en';
    try { const l = new Intl.Locale(`und-${country}`).maximize(); locale = `${l.language}-${l.script}-${country}`; } catch {}
    nativeLocaleCache.set(country, locale);
  }
  return nativeLocaleCache.get(country);
}

// { native: 'Deutschland', local: 'Alemania' (in the interface language), dial: '49' }
export function countryNames(code){
  const local = nameIn(getLang(), 'region', code) || nameIn('en', 'region', code) || code;
  const native = nameIn(nativeLocale(code), 'region', code) || local;
  return { native, local, dial: callingCode(code) };
}

const countryTags = new Map();
export function countrySearchText(code){
  if (!countryTags.has(code)) {
    const names = new Set([code, `+${callingCode(code)}`, nameIn(nativeLocale(code), 'region', code)]);
    for (const lang of TAG_LANGS) names.add(nameIn(lang, 'region', code));
    countryTags.set(code, fold([...names].filter(Boolean).join(' | ')));
  }
  return countryTags.get(code) + ' | ' + fold(nameIn(getLang(), 'region', code));
}

// { native: 'Deutsch', local: 'alemán' (in the interface language) }
export function languageNames(code){
  const native = (LANGUAGES.find(l => l.code === code) || {}).name || nameIn(code, 'language', code) || code;
  const local = nameIn(getLang(), 'language', code) || native;
  return { native, local };
}

const languageTags = new Map();
export function languageSearchText(code){
  if (!languageTags.has(code)) {
    const names = new Set([code, languageNames(code).native, nameIn(code, 'language', code)]);
    for (const lang of TAG_LANGS) names.add(nameIn(lang, 'language', code));
    languageTags.set(code, fold([...names].filter(Boolean).join(' | ')));
  }
  return languageTags.get(code);
}

// Search: every word typed must appear in the tags (accents and case ignored)
export function matches(text, query){
  const words = fold(query).trim().split(/\s+/).filter(Boolean);
  return words.every(w => text.includes(w));
}
